INSERT INTO recipe (recipe_id, recipe_name, description, instructions, cooking_time, servings, image_url, source_url, dish_type_id, cooking_method_id) VALUES
(5686755, 'Vịt ram thơm với nước dừa canh bí đỏ sườn non “ rau muống xào tỏi “', 'Vịt ram thơm với nước dừa canh bí đỏ sườn non “ rau muống xào tỏi “', 'Bước 1: Vịt rửa sạch bằng muối ( lúc làm vịt mẹ mình đã rửa kỹ rồi, nên mình khi ăn chỉ rửa lại nước muối thôi vì vịt nhà nên ko hôi như ở chợ bán “ vịt chặt miếng vừa ăn,thơm cắt miếng, tỏi ớt đập nhuyễn. Vịt cho 1 cafe hạt nêm + 1 vá canh nước mắm + cơm đường, ít tiêu để 10ph rồi nấu.
